<script>
function exportReport(){
 const esc=v=>String(v).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
 const kpis=[...document.querySelectorAll('.kpi')].map(k=>`<td><small>${esc(k.querySelector('span').innerText)}</small><br><b>${esc(k.querySelector('strong').innerText)}</b></td>`).join('');
 const alerts=[...document.querySelectorAll('.alert-item')].map(a=>`<li>${esc(a.innerText)}</li>`).join('');
 const table=document.getElementById('reportTable').outerHTML;
 const html=`<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:Arial,sans-serif;color:#172b4d;padding:24px}h1{color:#10264b;margin-bottom:4px}p{color:#526785}table{border-collapse:collapse;width:100%;margin:16px 0}th{background:#10264b;color:#fff}td,th{border:1px solid #cbd7e6;padding:9px;text-align:left}td b{font-size:15px;color:#10264b}small{color:#526785}ul{background:#fff7dc;border:1px solid #ecd486;padding:14px 28px}</style></head><body><h1>${esc(@json($baslik))}</h1><p>${esc(@json($firmaAdi))} · ${esc(@json($donem->translatedFormat('F Y')))}</p><h2>Yönetici Özeti</h2><table><tr>${kpis}</tr></table><h2>Kontrol ve Uyarılar</h2><ul>${alerts}</ul><h2>${esc(document.querySelector('#reportTable').closest('.report-panel').querySelector('h2').innerText)}</h2>${table}</body></html>`;
 const blob=new Blob(['\ufeff'+html],{type:'application/vnd.ms-excel;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='{{ \Illuminate\Support\Str::slug($baslik) }}-{{ $donem->format('Y-m') }}.xls';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);
}
</script>
